def solve(n, prerequisites):
    graph = [[] for _ in range(n)]
    in_degree = [0] * n
    for a, b in prerequisites:
        graph[b].append(a)
        in_degree[a] += 1

    queue = []
    for i in range(n):
        if in_degree[i] == 0:
            queue.append(i)

    result = []
    count = 0
    while queue:
        node = queue.pop(0)
        result.append(node)
        count += 1
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if count == n:
        return result
    else:
        return []
```

